return items
  .filter(i => i.json && i.json.id && i.json.position)
  .map(i => {
    const j = i.json;
    const desc = (j.description || '').replace(/<[^>]+>/g, ' ');
    return { json: {
      job_title: j.position || '',
      company: j.company || '',
      job_url: j.url || (j.id ? ('https://remoteok.com/remote-jobs/' + j.id) : ''),
      source: 'RemoteOK',
      location_text: j.location || 'Worldwide',
      salary: [j.salary_min, j.salary_max].filter(Boolean).join('-'),
      description: desc,
      posted_date: j.date || '',
      tags: Array.isArray(j.tags) ? j.tags.join(', ') : ''
    }};
  });

const jobs = (items[0] && items[0].json && items[0].json.jobs) || [];
return jobs.map(j => ({ json: {
  job_title: j.title || '',
  company: j.company_name || '',
  job_url: j.url || '',
  source: 'Remotive',
  location_text: j.candidate_required_location || 'Worldwide',
  salary: j.salary || '',
  description: (j.description || '').replace(/<[^>]+>/g, ' '),
  posted_date: j.publication_date || '',
  tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.category || '')
}}));

return items.map(i => {
