// Wellfound, Dynamite Jobs, YC Work at a Startup, and Otta do not expose a public
// RSS/API feed and actively block simple scraping (Cloudflare / login walls).
// Wire up a scraping service (Apify, Browserless, ScrapingBee) here via an HTTP
// Request node and return normalized job objects in this exact shape:
// { job_title, company, job_url, source, location_text, salary, description, posted_date, tags }
// Returning [] keeps the rest of the workflow running until this is configured.
return [];

const keywords = ['async remote','asynchronous remote','worldwide remote','global remote','work from anywhere','remote data analyst','remote data scientist','remote ai marketing','remote marketing analyst','remote growth analyst','remote bi analyst','remote automation specialist','remote ai workflow consultant','data analyst','data scientist','business intelligence','marketing analyst','growth analyst','automation specialist','ai marketing','ai workflow'];

function hashId(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (h * 31 + str.charCodeAt(i)) | 0; }
  return 'job_' + Math.abs(h).toString(36);
}

return items
  .map(i => i.json)
  .filter(j => j.job_url)
  .filter(j => {
    const hay = (j.job_title + ' ' + j.description + ' ' + j.tags).toLowerCase();
    return keywords.some(k => hay.includes(k));
  })
  .map(j => ({ json: Object.assign({}, j, { job_id: hashId(j.job_url) }) }));

const existingUrls = new Set(items.map(i => (i.json.job_url || '').trim().toLowerCase()).filter(Boolean));
const existingKeys = new Set(items.map(i => ((i.json.company || '').trim().toLowerCase() + '|' + (i.json.job_title || '').trim().toLowerCase())).filter(k => k !== '|'));
const candidates = $('Keyword Match Filter').all();
const seenThisRun = new Set();
const out = [];
for (const c of candidates) {
  const url = (c.json.job_url || '').trim().toLowerCase();
  const key = (c.json.company || '').trim().toLowerCase() + '|' + (c.json.job_title || '').trim().toLowerCase();
  if (!url) continue;
  if (existingUrls.has(url) || existingKeys.has(key)) continue;
  if (seenThisRun.has(url) || seenThisRun.has(key)) continue;
  seenThisRun.add(url); seenThisRun.add(key);
  out.push(c);
}
return out;

const rejectPhrases = ['us only','u.s. only','canada only','uk only','u.k. only','eu only','europe only','australia only','must be based in','must live in','must be authorized to work in','local work permit required','hybrid','onsite','on-site','office required','remote within','fixed us hours','fixed eu hours'];
const allowPhrases = ['worldwide remote','global remote','work from anywhere','anywhere','apac remote','international contractors','contractor role','b2b contractor','hires via deel','hires via remote.com','hires via oyster','eor supported','remote first','distributed team'];

return items.map(item => {
  const j = item.json;
  const hay = (j.job_title + ' ' + j.location_text + ' ' + j.description).toLowerCase();
  const rejectHit = rejectPhrases.find(p => hay.includes(p));
  const allowHit = allowPhrases.find(p => hay.includes(p));
  const apacHit = hay.includes('apac remote') || hay.includes('asia pacific remote');
  let signal = 'unclear';
  if (rejectHit && !allowHit) signal = 'reject';
  else if (allowHit) signal = 'pass';
  return { json: Object.assign({}, j, {
    hard_filter_signal: signal,
    hard_filter_reason: rejectHit ? ('Contains restrictive phrase: "' + rejectHit + '"') : (allowHit ? ('Contains allow phrase: "' + allowHit + '"') : 'No explicit worldwide/anywhere language found'),
    allow_hit: allowHit || '',
    apac_hit: apacHit,
    reject_category: rejectHit || ''
  }) };
});

return items.map((item, i) => {
  const orig = $('Hard Filter (Taiwan Rules)').itemMatching(i).json;
  let parsed;
  try {
    const text = item.json.content[0].text;
    const cleaned = text.trim().replace(/^```json\s*|```$/g, '');
    parsed = JSON.parse(cleaned);
  } catch (e) {
    parsed = { taiwan_eligible: 'unclear', reason: 'AI response could not be parsed', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
  }
  return { json: Object.assign({}, orig, {
    taiwan_eligible: parsed.taiwan_eligible,
    taiwan_reason: parsed.reason,
    location_risk: parsed.location_risk,
    timezone_risk: parsed.timezone_risk,
    contractor_possible: parsed.contractor_possible,
    ai_decision: parsed.decision
  }) };
});

const negPhrases = ['strict 9 to 5','strict 9-5','fixed us hours','fixed est hours','fixed pst hours','fixed cet hours','daily live calls required','must overlap full business day'];
const posPhrases = [['async', 25], ['asynchronous', 25], ['low meeting culture', 20], ['work across time zones', 20], ['work across timezones', 20], ['flexible hours', 20], ['flexible schedule', 20], ['distributed team', 15], ['remote first', 10]];

return items.map(item => {
  const j = item.json;
  const hay = (j.description + ' ' + j.job_title).toLowerCase();
  const negHit = negPhrases.find(p => hay.includes(p));
  let points = 0, matched = '';
  for (const pair of posPhrases) {
    const p = pair[0], pts = pair[1];
    if (hay.includes(p) && pts > points) { points = pts; matched = p; }
  }
  let level = 'none';
  if (points >= 25) level = 'high'; else if (points >= 15) level = 'medium'; else if (points > 0) level = 'low';
  return { json: Object.assign({}, j, {
    async_reject: !!negHit,
    async_reject_reason: negHit ? ('Requires fixed hours: "' + negHit + '"') : '',
    async_level: level,
    async_points: negHit ? 0 : points,
    async_matched_phrase: matched
  }) };
});

const primary = ['data analyst','data scientist','junior data scientist','business intelligence analyst','bi analyst','marketing analyst','performance marketing analyst','growth analyst','ai marketing specialist','ai automation specialist','ai workflow consultant','creative strategist','martech analyst'];
const adjacent = ['marketing','data','automation','analytics','growth','business intelligence'];

return items.map(item => {
  const j = item.json;
  const hay = (j.job_title + ' ' + j.description + ' ' + j.tags).toLowerCase();
  const primaryHit = primary.find(p => hay.includes(p));
  const adjacentHit = !primaryHit && adjacent.find(p => hay.includes(p));
  const category = primaryHit || (adjacentHit ? ('adjacent: ' + adjacentHit) : 'general');
  return { json: Object.assign({}, j, {
    role_category: category,
    role_points: primaryHit ? 25 : (adjacentHit ? 15 : 0)
  }) };
});

function taiwanPoints(j) {
  if (j.allow_hit) return 40;
  if (j.apac_hit) return 30;
  if (j.hard_filter_signal === 'reject') return 0;
  if (j.taiwan_eligible === 'yes') return 30;
  if (j.taiwan_eligible === 'unclear') return 20;
  return 0;
}
function salaryPoints(salaryStr) {
  if (!salaryStr) return 0;
  const nums = String(salaryStr).replace(/,/g, '').match(/\d+(\.\d+)?/g);
  if (!nums) return 10;
  let val = Math.max.apply(null, nums.map(Number));
  if (val > 15000) val = val / 12;
  if (val >= 5000) return 25;
  if (val >= 3000) return 15;
  return 10;
}

return items.map(item => {
  const j = item.json;
  const tPts = taiwanPoints(j);
  const aPts = j.async_points || 0;
  const rPts = j.role_points || 0;
  const sPts = salaryPoints(j.salary);
  const score = Math.min(100, tPts + aPts + rPts + sPts);
  const whyParts = [];
  if (tPts >= 30) whyParts.push('Explicitly open to Taiwan/worldwide remote');
  else if (tPts > 0) whyParts.push('Likely open to remote work outside fixed countries');
  if (rPts >= 25) whyParts.push('Strong role match (' + j.role_category + ')');
  else if (rPts > 0) whyParts.push('Adjacent role match (' + j.role_category + ')');
  if (aPts >= 20) whyParts.push('Async-friendly (' + j.async_level + ')');
  if (sPts >= 15) whyParts.push("Salary meets Jerry's target range");
  return { json: Object.assign({}, j, {
    score: score,
    score_breakdown: 'taiwan:' + tPts + ' async:' + aPts + ' role:' + rPts + ' salary:' + sPts,
    why_good_fit: whyParts.join('; ') || 'Meets baseline eligibility and role criteria',
    low_score_reason: 'Score ' + score + ' is below the 70-point keep threshold'
  }) };
});

return items.map(item => {
  const j = item.json;
  const locOk = j.location_risk === 'low';
  const tzOk = j.timezone_risk === 'low' || j.timezone_risk === 'medium';
  let decision = 'manual_check';
  let reason = '';
  if (j.taiwan_eligible === 'no' || j.location_risk === 'high' || j.timezone_risk === 'high' || j.score < 70) {
    decision = 'reject';
    if (j.taiwan_eligible === 'no') reason = 'AI determined not Taiwan-eligible';
    else if (j.location_risk === 'high') reason = 'High location risk';
    else if (j.timezone_risk === 'high') reason = 'High timezone risk';
    else reason = 'Score below threshold';
  } else if (j.taiwan_eligible === 'yes' && j.score >= 85 && (j.async_level === 'high' || j.async_level === 'medium') && locOk && tzOk) {
    decision = 'apply_immediately';
  } else if (j.taiwan_eligible === 'unclear' && j.score >= 85 && j.location_risk === 'medium') {
    decision = 'manual_check';
  } else if (j.score >= 70) {
    decision = 'manual_check';
  }
  return { json: Object.assign({}, j, {
    decision: decision,
    final_reject_reason: decision === 'reject' ? reason : '',
    application_status: decision === 'apply_immediately' ? 'ready_to_apply' : 'not_applied'
  }) };
});

