return items.map((item, i) => {
  const orig = $('Score >= 85 (Instant Alert)?').itemMatching(i).json;
  let letter = '';
  try { letter = item.json.content[0].text; } catch (e) { letter = 'Cover letter draft failed to generate.'; }
  return { json: Object.assign({}, orig, { cover_letter: letter }) };
});

const today = $now.toFormat('yyyy-LL-dd');
const filteredAll = $('Get Today\'s Filtered Jobs').all().map(i => i.json).filter(j => j.date_found === today);
const rejectedAll = $('Get Today\'s Rejected Jobs').all().map(i => i.json).filter(j => j.date_rejected === today);

const top = filteredAll
  .filter(j => j.decision !== 'reject')
  .sort((a, b) => Number(b.score) - Number(a.score))
  .slice(0, 8);

const manualCheck = filteredAll.filter(j => j.taiwan_eligible === 'unclear' && Number(j.score) >= 85);

function countReason(list, needles) {
  return list.filter(j => needles.some(n => (j.reason || '').toLowerCase().includes(n))).length;
}
const rejUsOnly = countReason(rejectedAll, ['us only', 'u.s. only']);
const rejEuOnly = countReason(rejectedAll, ['eu only', 'europe only']);
const rejHybrid = countReason(rejectedAll, ['hybrid', 'onsite', 'on-site']);
const rejTimezone = countReason(rejectedAll, ['timezone', 'fixed us hours', 'fixed eu hours', 'fixed est', 'fixed pst', 'fixed cet', 'overlap full business day']);

let msg = 'Daily Taiwan Eligible Async Remote Jobs — ' + today + '\n\nTop jobs today:\n\n';
top.forEach((j, idx) => {
  msg += (idx + 1) + '. ' + j.job_title + '\n';
  msg += 'Company: ' + j.company + '\n';
  msg += 'Score: ' + j.score + '\n';
  msg += 'Taiwan eligible: ' + j.taiwan_eligible + '\n';
  msg += 'Reason: ' + j.taiwan_reason + '\n';
  msg += 'Async level: ' + j.async_level + '\n';
  msg += 'Timezone risk: ' + j.timezone_risk + '\n';
  msg += 'Salary: ' + (j.salary || 'Not listed') + '\n';
  msg += 'Why it fits Jerry: ' + j.why_good_fit + '\n';
  msg += 'Apply link: ' + j.job_url + '\n\n';
});
if (top.length === 0) msg += '(No jobs cleared the score-70 bar today.)\n\n';

msg += 'Manual check:\n';
if (manualCheck.length === 0) {
  msg += '(None — no unclear-but-high-scoring jobs today.)\n';
} else {
  manualCheck.forEach(j => { msg += '- ' + j.job_title + ' at ' + j.company + ' (score ' + j.score + ') — ' + j.job_url + '\n'; });
}

msg += '\nRejected summary:\n';
msg += 'US only: ' + rejUsOnly + '\n';
msg += 'EU / Europe only: ' + rejEuOnly + '\n';
msg += 'Hybrid / onsite: ' + rejHybrid + '\n';
msg += 'Timezone risk: ' + rejTimezone + '\n';
msg += 'Total rejected: ' + rejectedAll.length + '\n';

return [{ json: { message: msg, top_count: top.length, rejected_count: rejectedAll.length } }];
